{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "In non-human primates, oral evobrutinib (the query molecule) was detected in CSF at pharmacologically relevant doses, directly demonstrating meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Ibrutinib, a close analogue sharing the acrylamide-piperidine and phenoxyphenyl motifs, showed high BBB penetration with a CSF/plasma ratio of 28.7%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Ibrutinib rapidly penetrated the BBB in mice with a brain-to-plasma ratio of 0.7, supporting CNS access for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "A related BTK inhibitor with an acrylamide-piperidine scaffold had acceptable brain exposure in rats (Kp,uu 0.37), supporting meaningful CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Compound 27, another acrylamide-piperidine BTK inhibitor, showed favorable brain exposure in rats as measured by Kp,uu.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass: the query molecule (evobrutinib) was directly detected in NHP CSF at pharmacologically relevant doses, and closely related BTK inhibitors with the same acrylamide-piperidine/phenoxyphenyl scaffold consistently show meaningful brain penetration in rats, mice, and humans.",
  "evidence_gaps": [
    "No quantitative human Kp,uu for the query molecule itself is provided; evidence relies on NHP CSF detection and closely related BTK inhibitor data.",
    "Potential contribution of efflux transporters to the query's brain exposure is not directly measured, though the overall analogue pattern indicates meaningful CNS access."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

